Here is a Python script to access the `/proc/self/environ` file and print its contents:

```python
import subprocess

def get_environ():
    try:
        # Read the /proc/self/environ file
        environ = subprocess.check_output(['cat', '/proc/self/environ']).decode('utf-8').split('\0')
        return environ
    except subprocess.CalledProcessError as e:
        print(f"Failed to read /proc/self/environ: {e}")
        return None

if __name__ == "__main__":
    environ = get_environ()
    if environ:
        for item in environ:
            print(item)
```

